 function getRevealClip(){if(clipRevision===discovery.revision&&revealClip)return revealClip;const path=new Path2D();for(let y=0;y<world.rows;y++){let start=-1;for(let x=0;x<=world.cols;x++){const known=x<world.cols&&discovery.explored[y*world.cols+x];if(known&&start<0)start=x;if(!known&&start>=0){const [ax,ay]=project(start,y),[bx,by]=project(x-1,y);poly(path,[[ax-14,ay-43],[bx+12,by-43],[bx+14,by+9],[ax-12,ay+9]]);start=-1;}}}if(discovery.foundBurrow&&burrow)path.rect(burrow.x,burrow.y,burrow.w,burrow.h);clipRevision=discovery.revision;revealClip=path;return path;}
